<?php
declare(strict_types=1);
require __DIR__.'/app/qhse.php';header('Content-Type: application/json; charset=utf-8');
try{$user=require_verified();verify_csrf();$kind=(string)($_POST['kind']??'');if($kind==='unit'){$code=strtoupper(preg_replace('/\s+/','',qhse_text($_POST,'code',30,true)));$label=qhse_text($_POST,'label',80,true);if(rows('SELECT 1 FROM equipment_measurement_units WHERE code=? AND (owner_id IS NULL OR owner_id=?)',[$code,$user['owner_id']]))throw new DomainException('That unit already exists.',409);$id=uuid();db()->prepare("INSERT INTO equipment_measurement_units(id,owner_id,code,label,unit_group) VALUES(?,?,?,?,'SIZE')")->execute([$id,$user['owner_id'],$code,$label]);$result=['id'=>$id,'label'=>$label,'meta'=>$code,'code'=>$code,'message'=>'Measurement unit added.'];}else{$result=qhse_quick_create($user,$kind,$_POST);}if($kind==='equipment'){$size=filter_var($_POST['equipment_size']??null,FILTER_VALIDATE_FLOAT,FILTER_NULL_ON_FAILURE);$sizeUnit=strtoupper(qhse_text($_POST,'equipment_size_unit',30));if($size!==null&&$size<0)throw new DomainException('Equipment size cannot be negative.',422);if($sizeUnit!==''&&!rows('SELECT 1 FROM equipment_measurement_units WHERE code=? AND (owner_id IS NULL OR owner_id=?)',[$sizeUnit,$user['owner_id']]))throw new DomainException('Choose a saved equipment-size unit.',422);$owner=qhse_text($_POST,'equipment_owner',80);$ownerUser=null;$ownerCustomer=null;if($owner!==''){[$ownerType,$ownerId]=array_pad(explode(':',$owner,2),2,'');if($ownerType==='USER'&&rows('SELECT 1 FROM users WHERE id=? AND owner_id=?',[$ownerId,$user['owner_id']]))$ownerUser=$ownerId;elseif($ownerType==='CUSTOMER'&&rows('SELECT 1 FROM commercial_customers WHERE id=? AND organization_id=?',[$ownerId,$user['owner_id']]))$ownerCustomer=$ownerId;else throw new DomainException('Choose an equipment owner from your organization or clients.',422);}db()->prepare('UPDATE equipment SET equipment_size=?,equipment_size_unit=?,equipment_owner_user_id=?,equipment_owner_customer_id=? WHERE id=? AND owner_id=?')->execute([$size,$sizeUnit?:null,$ownerUser,$ownerCustomer,$result['id'],$user['owner_id']]);}http_response_code(201);echo json_encode(['ok'=>true]+$result,JSON_THROW_ON_ERROR);}catch(Throwable $error){http_response_code($error instanceof DomainException?$error->getCode():500);echo json_encode(['ok'=>false,'message'=>$error instanceof DomainException?$error->getMessage():'The record could not be created.'],JSON_THROW_ON_ERROR);}
